t.script:
//
lucide.createIcons();

    function openModal(title) {
      document.getElementById('modal-input-focus').value = title || 'ERP MoR Walkthrough';
      document.getElementById('modal-title').innerText = title || 'Schedule Live ERP Demo';
      const m = document.getElementById('erp-modal');
      m.classList.remove('hidden');
      m.classList.add('flex');
    }

    function closeModal() {
      const m = document.getElementById('erp-modal');
      m.classList.add('hidden');
      m.classList.remove('flex');
      document.getElementById('modal-form').classList.remove('hidden');
      document.getElementById('modal-success').classList.add('hidden');
    }

    function handleInquiry(e) {
      e.preventDefault();
      document.getElementById('modal-form').classList.add('hidden');
      document.getElementById('modal-success').classList.remove('hidden');
      lucide.createIcons();
    }

    function calcErp() {
      const tier = document.getElementById('erp-tier');
      const opt = tier.options[tier.selectedIndex];
      let price = parseInt(opt.value || '650000', 10);
      let days = opt.getAttribute('data-days') || '21';

      if (document.getElementById('erp-telebirr').checked) {
        price += 50000;
      }

      document.getElementById('erp-total-price').innerHTML = 
        price.toLocaleString() + ' <span class="text-lg text-slate-400">ETB</span>';
      document.getElementById('erp-timeline').innerText = days + ' Business Days';
    }

    window.addEventListener('DOMContentLoaded', calcErp);
//
